alter table public.notes enable row level security;

create policy "notes_select_own_or_public"
  on public.notes
  for select
  to authenticated
  using (
    user_id = auth.uid()
    or (is_public = true and auth.role() = 'authenticated')
  );

create policy "notes_insert_own"
  on public.notes
  for insert
  to authenticated
  with check (user_id = auth.uid());

create policy "notes_update_own"
  on public.notes
  for update
  to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create policy "notes_delete_own"
  on public.notes
  for delete
  to authenticated
  using (user_id = auth.uid());

-- Ensure service_role bypasses RLS (default behavior, but explicit grants)
grant all on public.notes to service_role;

-- Revoke direct table access from anon to force RLS enforcement
revoke all on public.notes from anon;
revoke all on public.notes from authenticated;

-- Grant necessary usage to authenticated
grant select, insert, update, delete on public.notes to authenticated;
```

