create schema private;

grant usage on schema private to authenticated;

create function private.is_member(p_team_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.team_members m where m.team_id = p_team_id and m.user_id = auth.uid())
$$;

create function private.is_editor(p_team_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.team_members m where m.team_id = p_team_id and m.user_id = auth.uid() and m.role = 'editor')
$$;

alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

create policy teams_select on public.teams
  for select to authenticated
  using (private.is_member(id));

create policy team_members_select on public.team_members
  for select to authenticated
  using (user_id = auth.uid());

create policy documents_select on public.documents
  for select to authenticated
  using (private.is_member(team_id) and deleted_at is null);

create policy documents_insert on public.documents
  for insert to authenticated
  with check (private.is_editor(team_id) and created_by = auth.uid() and deleted_at is null);

create policy documents_update on public.documents
  for update to authenticated
  using (private.is_editor(team_id))
  with check (private.is_editor(team_id) and created_by = auth.uid() and deleted_at is null);

create policy documents_delete on public.documents
  for delete to authenticated
  using (created_by = auth.uid());
