```sql
alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

create or replace function public.is_suspended(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select suspended from public.accounts where user_id = p_user_id),
    false
  );
$$;

create or replace function public.can_access_file(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.file_shares
    where file_id = p_file_id
      and shared_with = p_user_id
      and (expires_at is null or expires_at > now())
  );
$$;

create or replace function public.can_edit_shared_file(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.file_shares
    where file_id = p_file_id
      and shared_with = p_user_id
      and can_edit
      and (expires_at is null or expires_at > now())
  );
$$;

create or replace function public.is_file_owner(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.files
    where id = p_file_id and owner_id = p_user_id
  );
$$;

create or replace function public.can_manage_file_share(p_file_id bigint, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.files
    where id = p_file_id and owner_id = p_user_id
  );
$$;

create or replace function public.prevent_suspended_file_access()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_suspended(auth.uid()) then
    raise exception 'Suspended accounts cannot access files';
  end if;
  return new;
end;
$$;

create or replace function public.prevent_suspended_share_access()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_suspended(auth.uid()) then
    raise exception 'Suspended accounts cannot access shares';
  end if;
  return new;
end;
$$;

create or replace function public.prevent_suspended_account_access()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_suspended(auth.uid()) then
    raise exception 'Suspended accounts cannot access accounts';
  end if;
  return new;
end;
$$;

create trigger prevent_suspended_file_access
before insert or update or delete on public.files
for each row execute function public.prevent_suspended_file_access();

create trigger prevent_suspended_share_access
before insert or update or delete on public.file_shares
for each row execute function public.prevent_suspended_share_access();

create trigger prevent_suspended_account_access
before insert or update or delete on public.accounts
for each row execute function public.prevent_suspended_account_access();

create policy "files_select_owner_or_shared"
on public.files
for select
to authenticated
using (
  owner_id = auth.uid()
  or public.can_access_file(id, auth.uid())
);

create policy "files_insert_owner"
on public.files
for insert
to authenticated
with check (
  owner_id = auth.uid()
  and not public.is_suspended(auth.uid())
);

create policy "files_update_owner_or_edit_shared"
on public.files
for update
to authenticated
using (
  owner_id = auth.uid()
  or public.can_edit_shared_file(id, auth.uid())
)
with check (
  owner_id = auth.uid()
  or public.can_edit_shared_file(id, auth.uid())
);

create policy "files_delete_owner"
on public.files
for delete
to authenticated
using (
  owner_id = auth.uid()
  and not public.is_suspended(auth.uid())
);

create policy "file_shares_select_owner_or_target"
on public.file_shares
for select
to authenticated
using (
  public.can_manage_file_share(file_id, auth.uid())
  or shared_with = auth.uid()
);

create policy "file_shares_insert_owner"
on public.file_shares
for insert
to authenticated
with check (
  public.is_file_owner(file_id, auth.uid())
  and not public.is_suspended(auth.uid())
);

create policy "file_shares_update_owner"
on public.file_shares
for update
to authenticated
using (
  public.can_manage_file_share(file_id, auth.uid())
)
with check (
  public.can_manage_file_share(file_id, auth.uid())
);

create policy "file_shares_delete_owner"
on public.file_shares
for delete
to authenticated
using (
  public.can_manage_file_share(file_id, auth.uid())
  and not public.is_suspended(auth.uid())
);

create policy "accounts_select_self"
on public.accounts
for select
to authenticated
using (
  user_id = auth.uid()
  and not public.is_suspended(auth.uid())
);

revoke all on public.accounts from anon, authenticated;
revoke all on public.files from anon, authenticated;
revoke all on public.file_shares from anon, authenticated;

grant select on public.accounts to authenticated;
grant select, insert, update, delete on public.files to authenticated;
grant select, insert, update, delete on public.file_shares to authenticated;

grant usage, select on all sequences in schema public to authenticated;

grant all on public.accounts to service_role;
grant all on public.files to service_role;
grant all on public.file_shares to service_role;
grant usage, select on all sequences in schema public to service_role;
```

