```sql
-- Enable RLS on tables
alter table public.finance_staff enable row level security;
alter table public.invoices enable row level security;

-- Helper function to check if user is finance staff
create or replace function public.is_finance_staff(check_user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.finance_staff where user_id = check_user_id
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if invoice is draft
create or replace function public.is_invoice_draft(invoice_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.invoices 
    where id = invoice_id and status = 'draft'
  );
end;
$$ language plpgsql security definer;

-- R1: Read invoices - creator or finance staff
create policy "invoices_select"
  on public.invoices
  for select
  to authenticated
  using (
    created_by = auth.uid() 
    or public.is_finance_staff(auth.uid())
  );

-- R2: Create invoices - only as self, only as draft
create policy "invoices_insert"
  on public.invoices
  for insert
  to authenticated
  with check (
    created_by = auth.uid()
    and status = 'draft'
  );

-- R3, R4, R6: Update invoices with complex rules
create policy "invoices_update"
  on public.invoices
  for update
  to authenticated
  using (
    public.is_finance_staff(auth.uid())
    or (created_by = auth.uid() and status = 'draft')
  )
  with check (
    -- Never change created_by (R6)
    -- R3: creator of draft can change customer, amount, status to sent
    -- R4: finance staff can change sent to paid or void
    -- No one can change once not draft except status by finance staff
    (
      -- Current status is draft and user is creator
      created_by = auth.uid() 
      and status = 'draft'
      and (
        -- Can change to sent
        (new.status = 'sent' and new.customer is not null and new.amount is not null)
        -- Can keep as draft with any changes to customer/amount
        (new.status = 'draft' and new.customer is not null and new.amount is not null)
      )
    )
    or (
      -- Finance staff updating sent invoice
      public.is_finance_staff(auth.uid())
      and status = 'sent'
      and new.status in ('paid', 'void')
      and new.customer is null
      and new.amount is null
    )
  );

-- R5: Delete invoices - creator of draft only
create policy "invoices_delete"
  on public.invoices
  for delete
  to authenticated
  using (
    created_by = auth.uid()
    and status = 'draft'
  );

-- R7: Read own finance_staff status
create policy "finance_staff_select_own"
  on public.finance_staff
  for select
  to authenticated
  using (
    user_id = auth.uid()
  );

-- R7: No insert/update/delete on finance_staff through app
-- (no policies for these operations = denied for authenticated, anon has no policies)

-- R8: Anonymous visitors have no policies, so nothing accessible

-- Ensure service_role bypasses RLS (default Supabase behavior, but explicit grants)
grant all on public.finance_staff to service_role;
grant all on public.invoices to service_role;
grant usage on schema public to service_role;

-- Grant authenticated users appropriate table permissions
grant select, insert, update, delete on public.invoices to authenticated;
grant select on public.finance_staff to authenticated;
grant usage on schema public to authenticated;

-- Grant execute on helper functions
grant execute on function public.is_finance_staff(uuid) to authenticated;
grant execute on function public.is_invoice_draft(bigint) to authenticated;
```

