alter table public.reservations enable row level security;

create function public.is_restaurant_staff(p_restaurant_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.restaurant_staff s
    where s.restaurant_id = p_restaurant_id
      and s.user_id = auth.uid()
  );
$$;

create function public.reservation_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.id is distinct from old.id
     or new.restaurant_id is distinct from old.restaurant_id
     or new.user_id is distinct from old.user_id
     or new.reserved_for is distinct from old.reserved_for
     or new.party_size is distinct from old.party_size then
    raise exception 'cannot change reservation metadata';
  end if;

  if old.status <> 'booked' then
    raise exception 'only booked reservations can be changed';
  end if;

  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;

  if public.is_restaurant_staff(old.restaurant_id) then
    if old.reserved_for > now() then
      raise exception 'staff can only mark past reservations';
    end if;
    if new.status not in ('seated', 'no_show') then
      raise exception 'staff can only mark as seated or no_show';
    end if;
  else
    if old.user_id <> auth.uid() then
      raise exception 'only the user can change their own reservation';
    end if;
    if new.status <> 'cancelled' then
      raise exception 'only the user can cancel their own reservation';
    end if;
    if old.reserved_for <= now() then
      raise exception 'only future reservations can be cancelled';
    end if;
  end if;

  return new;
end;
$$;

create trigger reservation_guard_trigger
before update on public.reservations
for each row execute function public.reservation_guard();

create policy restaurants_select_authenticated
on public.restaurants
for select
to authenticated
using (true);

create policy reservations_select_own_or_staff
on public.reservations
for select
to authenticated
using (
  user_id = auth.uid()
  or public.is_restaurant_staff(restaurant_id)
);

create policy reservations_insert_own
on public.reservations
for insert
to authenticated
with check (
  user_id = auth.uid()
  and status = 'booked'
  and reserved_for > now()
);

create policy reservations_update_own_cancel_or_staff_mark
on public.reservations
for update
to authenticated
using (
  (user_id = auth.uid() and status = 'booked' and reserved_for > now())
  or (public.is_restaurant_staff(restaurant_id) and status = 'booked' and reserved_for <= now())
)
with check (
  (user_id = auth.uid() and status = 'cancelled')
  or (public.is_restaurant_staff(restaurant_id) and status in ('seated', 'no_show'))
);

revoke all on public.restaurants from public, anon, authenticated;
revoke all on public.restaurant_staff from public, anon, authenticated;
revoke all on public.reservations from public, anon, authenticated;
revoke all on sequence public.reservations_id_seq from public, anon, authenticated;

grant select on public.restaurants to authenticated;
grant select on public.restaurant_staff to authenticated;
grant select, insert, update on public.reservations to authenticated;
grant usage, select on sequence public.reservations_id_seq to authenticated;

grant all on public.restaurants to service_role;
grant all on public.restaurant_staff to service_role;
grant all on public.reservations to service_role;
grant all on sequence public.reservations_id_seq to service_role;
