create or replace function public.accept_invite(p_token text)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_org_id bigint;
  v_email text;
  v_role text;
  v_expires_at timestamptz;
  v_accepted_at timestamptz;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select i.org_id, i.role, i.expires_at, i.accepted_at
    into v_org_id, v_role, v_expires_at, v_accepted_at
  from public.invites i
  where i.token = p_token
  for update;

  if not found then
    raise exception 'unknown invite';
  end if;

  if v_accepted_at is not null then
    raise exception 'invite already accepted';
  end if;

  if v_expires_at <= now() then
    raise exception 'invite expired';
  end if;

  select (auth.jwt() ->> 'email')
    into v_email
  from dual;

  if v_email is null then
    raise exception 'email not found in jwt';
  end if;

  if lower(v_email) <> lower(invites.email) then
    raise exception 'email does not match invite';
  end if;

  update public.invites
     set accepted_at = now()
   where token = p_token;

  insert into public.org_members (org_id, user_id, role)
  values (v_org_id, v_uid, v_role);

  return v_org_id;
end;
$$;

