create or replace function public.is_staff(p_location_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.location_staff ls
    where ls.location_id = p_location_id
      and ls.user_id = auth.uid()
  );
$$;

create or replace function public.is_auditor()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (auth.jwt() -> 'app_metadata' ->> 'role') = 'auditor',
    false
  );
$$;

create or replace function public.can_edit_stock(p_location_id bigint, p_sku text, p_qty integer)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_is_frozen boolean;
begin
  if auth.uid() is null then
    return false;
  end if;

  if public.is_auditor() then
    return false;
  end if;

  select is_frozen into v_is_frozen
  from public.locations
  where id = p_location_id
  for update;

  if v_is_frozen is true then
    return false;
  end if;

  if not public.is_staff(p_location_id) then
    return false;
  end if;

  if p_qty is null then
    return false;
  end if;

  if p_qty < 0 then
    return false;
  end if;

  return true;
end;
$$;

