create function private.is_member(p_project_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.project_members m where m.project_id = p_project_id and m.user_id = auth.uid())
$$;

create function private.can_see_issue(p_project_id bigint, p_is_confidential boolean) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.project_members m
    join public.projects p on p.id = m.project_id
    where m.project_id = p_project_id
      and m.user_id = auth.uid()
      and (
        not p_is_confidential
        or m.role = 'maintainer'
        or exists (select 1 from public.issues i where i.id = p_is_confidential and i.project_id = p_project_id and (i.reporter_id = auth.uid() or i.assignee_id = auth.uid()))
      )
  )
$$;

create function private.can_update_issue(p_project_id bigint, p_is_confidential boolean) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.project_members m
    join public.projects p on p.id = m.project_id
    where m.project_id = p_project_id
      and m.user_id = auth.uid()
      and m.role in ('developer', 'maintainer')
      and (
        not p_is_confidential
        or m.role = 'maintainer'
      )
  )
$$;

alter table public.projects enable row level security;
alter table public.project_members enable row level security;
alter table public.issues enable row level security;

create policy projects_select on public.projects
  for select to authenticated
  using (private.is_member(id));

create policy project_members_select on public.project_members
  for select to authenticated
  using (private.is_member(project_id));

create policy issues_select on public.issues
  for select to authenticated
  using (private.can_see_issue(project_id, is_confidential));

create policy issues_insert on public.issues
  for insert to authenticated
  with check (reporter_id = auth.uid() and status = 'open' and private.is_member(project_id));

create policy issues_update on public.issues
  for update to authenticated
  using (private.can_see_issue(project_id, is_confidential))
  with check (private.can_update_issue(project_id, is_confidential));
