-- Helper functions
create or replace function public.is_project_member(p_project_id bigint, p_user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.project_members
    where project_id = p_project_id and user_id = p_user_id
  );
end;
$$ language plpgsql security definer;

create or replace function public.is_project_maintainer(p_project_id bigint, p_user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.project_members
    where project_id = p_project_id and user_id = p_user_id and role = 'maintainer'
  );
end;
$$ language plpgsql security definer;

create or replace function public.can_see_issue(p_issue_project_id bigint, p_issue_reporter_id uuid, p_issue_assignee_id uuid)
returns boolean as $$
declare
  current_user uuid := auth.uid();
begin
  if current_user is null then
    return false;
  end if;

  if p_issue_reporter_id = current_user or p_issue_assignee_id = current_user then
    return true;
  end if;

  return exists (
    select 1 from public.project_members
    where project_id = p_issue_project_id and user_id = current_user and role = 'maintainer'
  );
end;
$$ language plpgsql security definer;

-- Projects RLS
alter table public.projects enable row level security;

create policy "projects_select_members"
  on public.projects
  for select
  to authenticated
  using (public.is_project_member(id, auth.uid()));

-- Project members RLS
alter table public.project_members enable row level security;

create policy "project_members_select_members"
  on public.project_members
  for select
  to authenticated
  using (public.is_project_member(project_id, auth.uid()));

-- Issues RLS
alter table public.issues enable row level security;

create policy "issues_select_members"
  on public.issues
  for select
  to authenticated
  using (
    public.is_project_member(project_id, auth.uid())
    and (is_confidential = false or public.can_see_issue(project_id, reporter_id, assignee_id))
  );

create policy "issues_insert_members"
  on public.issues
  for insert
  to authenticated
  with check (
    reporter_id = auth.uid()
    and status = 'open'
    and public.is_project_member(project_id, auth.uid())
  );

create policy "issues_update_members"
  on public.issues
  for update
  to authenticated
  using (
    public.is_project_member(project_id, auth.uid())
    and (
      is_confidential = false
      or public.can_see_issue(project_id, reporter_id, assignee_id)
    )
  )
  with check (
    (
      public.is_project_member(project_id, auth.uid())
      and (
        (auth.uid() = reporter_id or public.is_project_maintainer(project_id, auth.uid()))
        and (
          public.is_project_member(project_id, auth.uid())
          and (
            (is_confidential = false or public.is_project_maintainer(project_id, auth.uid()))
            or (is_confidential = report_is_confidential and public.is_project_member(project_id, auth.uid()))
          )
        )
      )
    )
  );

-- Trigger to enforce update rules
create or replace function public.enforce_issue_update_rules()
returns trigger as $$
declare
  current_user uuid := auth.uid();
  old_is_confidential boolean := OLD.is_confidential;
  new_is_confidential boolean := NEW.is_confidential;
begin
  -- Prevent changing project_id
  if NEW.project_id != OLD.project_id then
    raise exception 'Cannot change project_id';
  end if;

  -- Prevent changing reporter_id
  if NEW.reporter_id != OLD.reporter_id then
    raise exception 'Cannot change reporter_id';
  end if;

  -- Prevent changing assignee_id to non-existent user
  if NEW.assignee_id is not distinct from OLD.assignee_id then
    -- keep same assignee is allowed
  elsif NEW.assignee_id is null then
    raise exception 'Assignee cannot be cleared';
  elsif not exists(select 1 from auth.users where id = NEW.assignee_id) then
    raise exception 'Invalid assignee_id';
  else
    raise exception 'Cannot change assignee_id';
  end if;

  -- Only maintainers can change is_confidential
  if new_is_confidential != old_is_confidential then
    if not public.is_project_maintainer(NEW.project_id, current_user) then
      raise exception 'Only maintainers can change is_confidential';
    end if;
  end if;

  -- Reporters cannot update issues (unless they are also in another role and it's the same issue)
  if OLD.reporter_id = current_user and NEW.id = OLD.id then
    if NEW.status != OLD.status then
      raise exception 'Reporters cannot change status';
    end if;
    if NEW.is_confidential != OLD.is_confidential then
      raise exception 'Reporters cannot change is_confidential';
    end if;
    if NEW.assignee_id != OLD.assignee_id then
      raise exception 'Reporters cannot change assignee_id';
    end if;
    if NEW.project_id != OLD.project_id then
      raise exception 'Cannot change project_id';
    end if;
    if NEW.reporter_id != OLD.reporter_id then
      raise exception 'Cannot change reporter_id';
    end if;
  end if;

  return NEW;
end;
$$ language plpgsql security definer;

create trigger enforce_issue_update_rules
  before update on public.issues
  for each row
  execute function public.enforce_issue_update_rules();

-- Prevent delete on issues
create policy "issues_no_delete"
  on public.issues
  for delete
  to authenticated
  using (false);

-- Prevent modifications to projects and project_members by app users
create policy "projects_no_modify"
  on public.projects
  for all
  to authenticated
  using (false);

create policy "project_members_no_modify"
  on public.project_members
  for all
  to authenticated
  using (false);

-- Service role bypasses RLS automatically, but explicit policies for completeness
create policy "projects_service_all"
  on public.projects
  for all
  to service_role
  using (true)
  with check (true);

create policy "project_members_service_all"
  on public.project_members
  for all
  to service_role
  using (true)
  with check (true);

create policy "issues_service_all"
  on public.issues
  for all
  to service_role
  using (true)
  with check (true);

-- Grants
grant select on public.projects to authenticated;
grant select on public.project_members to authenticated;
grant select, insert, update on public.issues to authenticated;
grant all on public.projects to service_role;
grant all on public.project_members to service_role;
grant all on public.issues to service_role;

-- Prevent anon access
revoke all on public.projects from anon;
revoke all on public.project_members from anon;
revoke all on public.issues from anon;
