-- Trigger to enforce update rules
create or replace function public.enforce_issue_update_rules()
returns trigger as $$
declare
  current_user uuid := auth.uid();
  old_is_confidential boolean := OLD.is_confidential;
  new_is_confidential boolean := NEW.is_confidential;
begin
  -- Prevent changing project_id
  if NEW.project_id != OLD.project_id then
    raise exception 'Cannot change project_id';
  end if;

  -- Prevent changing reporter_id
  if NEW.reporter_id != OLD.reporter_id then
    raise exception 'Cannot change reporter_id';
  end if;

  -- Prevent changing assignee_id to non-existent user
  if NEW.assignee_id is not distinct from OLD.assignee_id then
    -- keep same assignee is allowed
  elsif NEW.assignee_id is null then
    raise exception 'Assignee cannot be cleared';
  elsif not exists (select 1 from auth.users where id = NEW.assignee_id) then
    raise exception 'Invalid assignee_id';
  end if;

  -- Prevent changing status to anything other than open->in_progress->closed cycle or maintainers changing
  if OLD.status = 'closed' then
    raise exception 'Cannot update closed issues';
  end if;

  -- Check if current user is a reporter - if so, cannot update anything
  if current_user = OLD.reporter_id then
    raise exception 'Reporters cannot update issues';
  end if;

  -- Check if current user is not a maintainer and trying to change confidentiality
  if old_is_confidential != new_is_confidential and not public.is_project_maintainer(OLD.project_id, current_user) then
    raise exception 'Only maintainers can change confidentiality';
  end if;

  -- Check if new status is valid transition
  if OLD.status = 'open' and NEW.status = 'in_progress' then
    -- developer or maintainer can start work
  elsif OLD.status = 'in_progress' and NEW.status = 'closed' then
    -- developer or maintainer can close
  else
    raise exception 'Invalid status transition';
  end if;

  return NEW;
end;
$$ language plpgsql security definer;

