  for select to authenticated
  using (patient_id = auth.uid() or exists (select 1 from public.pharmacists p where p.user_id = auth.uid()));

create policy dispenses_select on public.dispenses
  for select to authenticated
  using (exists (select 1 from public.prescriptions p where p.id = prescription_id and (p.patient_id = auth.uid() or exists (select 1 from public.pharmacists p2 where p2.user_id = auth.uid()))));

create function public.is_pharmacist() returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.pharmacists p where p.user_id = auth.uid())
$$;

create function public.dispense(p_prescription_id bigint) returns integer
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_refills integer;
begin
  if v_uid is null or not public.is_pharmacist() then
    raise exception 'only pharmacists can dispense';
  end if;
  select p.refills_left into v_refills from public.prescriptions p where p.id = p_prescription_id for update;
  if not found then
    raise exception 'unknown prescription';
  end if;
  if p.expires_at <= now() then
    raise exception 'prescription expired';
  end if;
  if p.patient_id = v_uid then
    raise exception 'cannot dispense your own prescription';
  end if;
  if v_refills <= 0 then
    raise exception 'no refills left';
  end if;
  update public.prescriptions set refills_left = v_refills - 1 where id = p_prescription_id;
  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at) values (p_prescription_id, v_uid, now());
  return v_refills - 1;
end
$$;

