  for select to authenticated
  using (exists (select 1 from public.prescriptions p where p.id = prescription_id and p.patient_id = auth.uid()) or exists (select 1 from public.pharmacists p where p.user_id = auth.uid()));

create function public.is_pharmacist() returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.pharmacists p where p.user_id = auth.uid())
