language plpgsql security definer set search_path = ''
as $$
declare
  v_pharmacist_id uuid := auth.uid();
  v_refills integer;
begin
  if v_pharmacist_id is null or not public.is_pharmacist() then
    raise exception 'only pharmacists can dispense';
  end if;

  if p_prescription_id is null then
    raise exception 'invalid prescription id';
  end if;

  select refills_left into v_refills
    from public.prescriptions p where p.id = p_prescription_id
   for update;

  if not found then
    raise exception 'unknown prescription';
  end if;

  if p_prescription_id = v_pharmacist_id then
    raise exception 'cannot dispense your own prescription';
  end if;

  if public.has_expired(p.expires_at) then
    raise exception 'prescription expired';
  end if;

  if v_refills_left <= 0 then
    raise exception 'no refills left';
  end if;

  update public.prescriptions set refills_left = refills_left - 1
    where id = p_prescription_id;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
    values (p_prescription_id, v_pharmacist_id, now());

  return v_refills - 1;
end
$$;

