-- Enable RLS on all tables
alter table public.reviewers enable row level security;
alter table public.proposals enable row level security;
alter table public.reviews enable row level security;

-- Helper function to check if user is a reviewer
create or replace function public.is_reviewer(p_user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.reviewers where user_id = p_user_id
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if proposal is undecided
create or replace function public.proposal_undecided(p_proposal_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.proposals where id = p_proposal_id and status != 'accepted' and status != 'rejected'
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if proposal has a decision
create or replace function public.proposal_has_decision(p_proposal_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.proposals where id = p_proposal_id and (status = 'accepted' or status = 'rejected')
  );
end;
$$ language plpgsql security definer;

-- Prevent updates to reviews table via direct table access
create or replace function public.prevent_review_update()
returns trigger as $$
begin
  if TG_OP = 'UPDATE' and auth.role() != 'service_role' then
    raise exception 'Reviews can only be modified through the API';
  end if;
  return NEW;
end;
$$ language plpgsql security definer;

create trigger prevent_review_update
before update on public.reviews
for each row execute function public.prevent_review_update();

-- Prevent updates to reviewers table
create or replace function public.prevent_reviewer_update()
returns trigger as $$
begin
  if TG_OP = 'UPDATE' and auth.role() != 'service_role' then
    raise exception 'Reviewers cannot be modified through the app';
  end if;
  return NEW;
end;
$$ language plpgsql security definer;

create trigger prevent_reviewer_update
before update on public.reviewers
for each row execute function public.prevent_reviewer_update();

-- Prevent deletes on all tables by users
create or replace function public.prevent_delete()
returns trigger as $$
begin
  if auth.role() = 'anon' or auth.role() = 'authenticated' then
    raise exception 'Delete not allowed for users';
  end if;
  return NEW;
end;
$$ language plpgsql security definer;

create trigger prevent_delete_reviews
before delete on public.reviews
for each row execute function public.prevent_delete();

create trigger prevent_delete_proposals
before delete on public.proposals
for each row execute function public.prevent_delete();

create trigger prevent_delete_reviewers
before delete on public.reviewers
for each row execute function public.prevent_delete();

-- Reviewers policies
create policy "reviewers_select_own"
on public.reviewers
for select
to authenticated
using (user_id = auth.uid());

-- Proposals policies
create policy "proposals_select_speaker_or_reviewer"
on public.proposals
for select
to authenticated
using (
  speaker_id = auth.uid() 
  or public.is_reviewer(auth.uid())
);

create policy "proposals_insert_own"
on public.proposals
for insert
to authenticated
with check (
  speaker_id = auth.uid() 
  and status = 'submitted'
);

create policy "proposals_update_own_undecided"
on public.proposals
for update
to authenticated
using (
  speaker_id = auth.uid() 
  and (status = 'submitted' or status = 'accepted' or status = 'rejected')
)
with check (
  speaker_id = auth.uid()
);

-- Reviews policies
create policy "reviews_select_own"
on public.reviews
for select
to authenticated
using (reviewer_id = auth.uid());

create policy "reviews_select_speaker_with_decision"
on public.reviews
for select
to authenticated
using (
  public.proposal_has_decision(proposal_id)
  and exists (
    select 1 from public.proposals 
    where id = reviews.proposal_id and speaker_id = auth.uid()
  )
);

create policy "reviews_insert_own_undecided_non_own_proposal"
on public.reviews
for insert
to authenticated
with check (
  reviewer_id = auth.uid() 
  and public.proposal_undecided(proposal_id)
  and not public.is_reviewer(proposal_id::uuid) -- reviewer_id cannot match proposal_id
);

create policy "reviews_update_own_undecided"
on public.reviews
for update
to authenticated
using (
  reviewer_id = auth.uid() 
  and public.proposal_undecided(proposal_id)
)
with check (
  reviewer_id = auth.uid()
  and public.proposal_undecided(proposal_id)
);

-- Revoke public access and grant appropriate permissions
revoke all on public.reviewers from anon, authenticated;
revoke all on public.proposals from anon, authenticated;
revoke all on public.reviews from anon, authenticated;

grant select on public.reviewers to authenticated;
grant select, insert, update on public.proposals to authenticated;
grant select, insert, update on public.reviews to authenticated;

-- Ensure service_role has full access (bypasses RLS by default, but explicit grants)
grant all on public.reviewers to service_role;
grant all on public.proposals to service_role;
grant all on public.reviews to service_role;

-- Ensure helper functions are accessible
grant execute on function public.is_reviewer(uuid) to authenticated, service_role;
grant execute on function public.proposal_undecided(bigint) to authenticated, service_role;
grant execute on function public.proposal_has_decision(bigint) to authenticated, service_role;
