alter table public.reviewers enable row level security;
alter table public.proposals enable row level security;
alter table public.reviews enable row level security;

-- Helper function to check if user is a reviewer
create or replace function public.is_reviewer(p_user_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.reviewers where user_id = p_user_id
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if proposal is undecided
create or replace function public.proposal_undecided(p_proposal_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.proposals where id = p_proposal_id and status != 'accepted' and status != 'rejected'
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if proposal has a decision
create or replace function public.proposal_has_decision(p_proposal_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.proposals where id = p_proposal_id and (status = 'accepted' or status = 'rejected')
  );
end;
$$ language plpgsql security definer;

-- Prevent updates to reviews table to avoid bypassing RLS
create or replace function public.prevent_review_update()
returns trigger as $$
begin
  if current_user = 'service_role' then
    return new;
  end if;
  raise exception 'reviews table can only be modified via insert';
end;
$$ language plpgsql security definer;

create trigger prevent_review_update
before update on public.reviews
for each row
execute function public.prevent_review_update();

-- Prevent updates to reviewers table
create or replace function public.prevent_reviewer_update()
returns trigger as $$
begin
  if current_user = 'service_role' then
    return new;
  end if;
  raise exception 'reviewers table can only be modified via insert';
end;
$$ language plpgsql security definer;

create trigger prevent_reviewer_update
before update on public.reviewers
for each row
execute function public.prevent_reviewer_update();

-- reviewers table policies
create policy "reviewers_select_self"
  on public.reviewers
  for select
  to authenticated
  using (user_id = auth.uid());

-- proposals table policies
create policy "proposals_select_own_or_reviewer"
  on public.proposals
  for select
  to authenticated
  using (
    speaker_id = auth.uid()
    or public.is_reviewer(auth.uid())
  );

create policy "proposals_insert_own"
  on public.proposals
  for insert
  to authenticated
  with check (
    speaker_id = auth.uid()
    and status = 'submitted'
  );

create policy "proposals_update_own_undecided"
  on public.proposals
  for update
  to authenticated
  using (
    speaker_id = auth.uid()
    and (status = 'submitted' or status = 'accepted')
  )
  with check (
    speaker_id = auth.uid()
  );

-- reviews table policies
create policy "reviews_select_own_or_proposal_decision"
  on public.reviews
  for select
  to authenticated
  using (
    reviewer_id = auth.uid()
    or public.proposal_has_decision(proposal_id)
  );

create policy "reviews_insert_own_undecided"
  on public.reviews
  for insert
  to authenticated
  with check (
    reviewer_id = auth.uid()
    and public.is_reviewer(auth.uid())
    and public.proposal_undecided(proposal_id)
    and not exists (
      select 1 from public.reviews
      where proposal_id = reviews.proposal_id
        and reviewer_id = reviews.reviewer_id
    )
  );

create policy "reviews_update_own_undecided"
  on public.reviews
  for update
  to authenticated
  using (
    reviewer_id = auth.uid()
    and public.proposal_undecided(proposal_id)
  )
  with check (
    reviewer_id = auth.uid()
    and public.proposal_undecided(proposal_id)
  );

-- Revoke all from anon and authenticated, then grant minimal necessary
revoke all on public.reviewers from anon, authenticated;
revoke all on public.proposals from anon, authenticated;
revoke all on public.reviews from anon, authenticated;

grant select on public.reviewers to authenticated;
grant select, insert, update on public.proposals to authenticated;
grant select, insert, update on public.reviews to authenticated;

grant all on public.reviewers to service_role;
grant all on public.proposals to service_role;
grant all on public.reviews to service_role;

grant usage, select on all sequences in schema public to authenticated, service_role;
