returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id <> old.id
     or new.unit_id <> old.unit_id
     or new.valid_until <> old.valid_until then
    raise exception 'Only plate can be changed on a permit';
  end if;

  if old.revoked and new.revoked = false then
    raise exception 'Cannot un-revoke a permit';
  end if;

  if public.is_hoa_admin() then
    return new;
  end if;

  if old.revoked then
    raise exception 'Cannot modify a revoked permit';
  end if;

  return new;
end;
