-- Enable RLS on tables
alter table public.residents enable row level security;
alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

-- Helper function: check if user is HOA admin
create or replace function public.is_hoa_admin(user_uuid uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.hoa_admins where user_id = user_uuid
  );
end;
$$ language plpgsql security definer;

-- Helper function: count active permits for a unit
create or replace function public.active_permit_count(unit_id bigint)
returns integer as $$
begin
  return (
    select count(*) from public.permits
    where permits.unit_id = $1 and revoked = false and valid_until >= current_date
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if new permit would exceed limit
create or replace function public.can_add_permit(p_user_id uuid, p_unit_id bigint)
returns boolean as $$
begin
  -- Must be a resident of the unit
  if not exists (select 1 from public.residents where unit_id = p_unit_id and user_id = p_user_id) then
    return false;
  end if;

  -- Check active permit count
  return public.active_permit_count(p_unit_id) < 2;
end;
$$ language plpgsql security definer;

-- Helper function: validate permit insert/update constraints
create or replace function public.validate_permit_insert(p_unit_id bigint, p_plate text, p_valid_until date)
returns boolean as $$
begin
  -- Valid until must be within 365 days from today
  if p_valid_until > current_date + interval '365 days' then
    return false;
  end if;

  -- Must not be revoked (new permits are never revoked)
  -- handled in policy, but validate here too
  return true;
end;
$$ language plpgsql security definer;

-- Helper function: validate permit update (plate only for residents)
create or replace function public.validate_permit_update(p_id bigint, p_unit_id bigint, p_plate text, p_valid_until date, p_revoked boolean)
returns boolean as $$
begin
  -- Get current permit state
  if not exists (select 1 from public.permits where id = p_id) then
    return false;
  end if;

  -- If updating revoked status, only admins can do so (and only to true)
  if p_revoked is distinct from null then
    if p_revoked = true then
      return public.is_hoa_admin(auth.uid());
    else
      return false; -- cannot un-revoke
    end if;
  end if;

  -- Check if updating plate only (residents)
  if p_valid_until is distinct from null or p_revoked is not null then
    return false;
  end if;

  -- Must be updating their own unit's permit
  if not exists (select 1 from public.residents where unit_id = p_unit_id and user_id = auth.uid()) then
    return false;
  end if;

  return true;
end;
$$ language plpgsql security definer;

-- Residents policies
create policy "residents_select_own"
  on public.residents
  for select
  to authenticated
  using (user_id = auth.uid());

create policy "residents_no_modify"
  on public.residents
  for all
  to authenticated
  using (false);

-- HOA admins policies (bypass via function or direct check)
create policy "hoa_admins_select"
  on public.residents
  for select
  to authenticated
  using (public.is_hoa_admin(auth.uid()));

-- Permits select policies
create policy "permits_select_resident"
  on public.permits
  for select
  to authenticated
  using (
    exists (
      select 1 from public.residents
      where unit_id = permits.unit_id and user_id = auth.uid()
    )
  );

create policy "permits_select_hoa_admin"
  on public.permits
  for select
  to authenticated
  using (public.is_hoa_admin(auth.uid()));

-- Permits insert policies
create policy "permits_insert_resident"
  on public.permits
  for insert
  to authenticated
  with check (
    public.can_add_permit(auth.uid(), unit_id)
    and not revoked
    and valid_until <= current_date + interval '365 days'
  );

-- Permits update policies
create policy "permits_update_resident"
  on public.permits
  for update
  to authenticated
  using (
    exists (
      select 1 from public.residents
      where unit_id = permits.unit_id and user_id = auth.uid()
    )
  )
  with check (
    exists (
      select 1 from public.residents
      where unit_id = permits.unit_id and user_id = auth.uid()
    )
    and not revoked
    and valid_until <= current_date + interval '365 days'
  );

create policy "permits_update_hoa_admin"
  on public.permits
  for update
  to authenticated
  using (public.is_hoa_admin(auth.uid()))
  with check (public.is_hoa_admin(auth.uid()));

-- Prevent deletes on permits (RLS default, but explicit trigger for safety)
create or replace function public.prevent_permit_delete()
returns trigger as $$
begin
  raise exception 'Permits cannot be deleted';
end;
$$ language plpgsql security definer;

create trigger prevent_permit_delete
  before delete on public.permits
  for each row
  execute function public.prevent_permit_delete();

-- Revoke all from public, anon
revoke all on public.residents from public, anon;
revoke all on public.hoa_admins from public, anon;
revoke all on public.permits from public, anon;

-- Grant to authenticated
grant select on public.residents to authenticated;
grant select on public.hoa_admins to authenticated;
grant select, insert, update on public.permits to authenticated;

-- Grant to service_role (bypasses RLS anyway, but explicit grants)
grant all on public.residents to service_role;
grant all on public.hoa_admins to service_role;
grant all on public.permits to service_role;

-- Grant usage on sequences
grant usage on all sequences in schema public to authenticated, service_role;

