-- Enable RLS on tables
alter table public.residents enable row level security;
alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

-- Helper function: check if user is HOA admin
create or replace function public.is_hoa_admin(user_uuid uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.hoa_admins where user_id = user_uuid
  );
end;
$$ language plpgsql security definer;

-- Helper function: count active permits for a unit
create or replace function public.active_permit_count(unit_id bigint)
returns integer as $$
begin
  return (
    select count(*) from public.permits
    where permits.unit_id = $1 and revoked = false and valid_until >= current_date
  );
end;
$$ language plpgsql security definer;

-- Helper function: check if new permit would exceed limit
create or replace function public.can_add_permit(p_unit_id bigint, p_author uuid)
returns boolean as $$
begin
  -- Must be a resident of the unit
  if not exists (select 1 from public.residents where unit_id = p_unit_id and user_id = p_author) then
    return false;
  end if;

  -- Count active permits excluding the one we're about to add
  return public.active_permit_count(p_unit_id) < 2;
end;
$$ language plpgsql security definer;

-- Helper function: check permit validity period
create or replace function public.is_valid_period(days integer)
returns boolean as $$
begin
  return days <= 365;
end;
$$ language plpgsql security definer;

-- Trigger: enforce permit insert rules (R2)
create or replace function public.enforce_permit_insert()
returns trigger as $$
begin
  -- Must be resident of the unit
  if not exists (select 1 from public.residents where unit_id = NEW.unit_id and user_id = auth.uid()) then
    raise exception 'Only residents can add permits for their unit';
  end if;

  -- Cannot be revoked
  if NEW.revoked then
    raise exception 'New permits cannot be revoked';
  end if;

  -- Valid for at most 365 days from today
  if NEW.valid_until < current_date or (NEW.valid_until - current_date) > interval '365 days' then
    raise exception 'Permit must be valid for at most 365 days from today';
  end if;

  return NEW;
end;
$$ language plpgsql security definer;

create trigger trg_enforce_permit_insert
before insert on public.permits
for each row execute function public.enforce_permit_insert();

-- Trigger: enforce permit update rules (R3, R4)
create or replace function public.enforce_permit_update()
returns trigger as $$
begin
  -- Prevent un-revoking (if revoked is true, it must stay true)
  if OLD.revoked = true and NEW.revoked = false then
    raise exception 'Cannot un-revoke a permit';
  end if;

  -- If updating from non-resident, only admins can change anything
  if not exists (select 1 from public.residents where unit_id = OLD.unit_id and user_id = auth.uid()) then
    -- Must be HOA admin
    if not public.is_hoa_admin(auth.uid()) then
      raise exception 'Only residents or HOA admins can update permits';
    end if;

    -- HOA admin: can only set revoked
    if OLD.revoked = false and NEW.revoked = true then
      return NEW;
    end if;

    raise exception 'HOA admins can only revoke permits';
  end if;

  -- Must be updating their own unit
  if OLD.unit_id <> NEW.unit_id then
    raise exception 'Cannot change unit_id of a permit';
  end if;

  -- Must be resident of the unit (or admin doing admin-only operations)
  if not exists (select 1 from public.residents where unit_id = OLD.unit_id and user_id = auth.uid()) then
    if not public.is_hoa_admin(auth.uid()) then
      raise exception 'Only residents or HOA admins can update permits';
    end if;
    -- HOA admin case handled above
    raise exception 'Invalid operation';
  end if;

  -- Residents: only change plate, cannot change validity or revoke status
  if OLD.revoked = false and NEW.revoked = false then
    if OLD.valid_until = NEW.valid_until and OLD.plate = NEW.plate then
      return NEW;
    end if;

    if OLD.valid_until <> NEW.valid_until or OLD.revoked <> NEW.revoked then
      raise exception 'Residents can only change plate, not validity or revoke status';
    end if;

    return NEW;
  end if;

  -- If we get here, it's not a simple resident plate change
  raise exception 'Invalid permit update';
end;
$$ language plpgsql security definer;

create trigger trg_enforce_permit_update
before update on public.permits
for each row execute function public.enforce_permit_update();

-- RLS policies for residents table (R5, R6)
create policy "residents_select_own"
  on public.residents
  for select
  to authenticated
  using (user_id = auth.uid());

create policy "residents_select_service_role"
  on public.residents
  for select
