  using (true);

-- RLS policies for permits table

-- Select policies (R1)
create policy "permits_select_resident_own_unit"
  on public.permits
  for select
  to authenticated
  using (
    exists (
      select 1 from public.residents
      where unit_id = permits.unit_id and user_id = auth.uid()
    )
  );

create policy "permits_select_hoa_admin"
  on public.permits
  for select
  to authenticated
  using (public.is_hoa_admin(auth.uid()));

create policy "permits_select_service_role"
  on public.permits
  for select
  to service_role
  using (true);

-- Insert policies (R2)
create policy "permits_insert_resident"
  on public.permits
  for insert
  to authenticated
  with check (
    exists (
      select 1 from public.residents
      where unit_id = permits.unit_id and user_id = auth.uid()
    )
    and not public.is_hoa_admin(auth.uid())
    and public.can_add_permit(permits.unit_id, auth.uid())
  );

create policy "permits_insert_service_role"
  on public.permits
  for insert
  to service_role
  with check (true);

-- Update policies (R3, R4)
create policy "permits_update_resident"
  on public.permits
  for update
  to authenticated
  using (
    exists (
      select 1 from public.residents
      where unit_id = permits.unit_id and user_id = auth.uid()
    )
  )
  with check (
    exists (
      select 1 from public.residents
      where unit_id = permits.unit_id and user_id = auth.uid()
    )
  );

create policy "permits_update_hoa_admin"
  on public.permits
  for update
  to authenticated
  using (public.is_hoa_admin(auth.uid()))
  with check (public.is_hoa_admin(auth.uid()));

create policy "permits_update_service_role"
  on public.permits
  for update
  to service_role
  using (true)
  with check (true);

-- Delete policies (R4 - nobody can delete, permits are never deleted)
-- No delete policies means delete is denied for all roles except service_role with no policy

-- Grant usage on sequences
grant usage on all sequences in schema public to authenticated;

-- Ensure proper permissions
grant select, insert, update on public.residents to authenticated;
grant select, insert, update on public.hoa_admins to authenticated;
grant select, insert, update on public.permits to authenticated;
