returns trigger as $$
begin
  -- Check if updating revoked status
  if old.revoked is distinct from new.revoked then
    if old.revoked = true and new.revoked = false then
      raise exception 'Cannot un-revoke a permit';
    end if;

    if public.is_hoa_admin(auth.uid()) then
      if new.valid_until is distinct from old.valid_until then
        raise exception 'HOA admins cannot change valid_until';
      end if;
      -- Check if user is still a resident (they shouldn't be if changing revoked on their own unit)
      if exists (select 1 from public.residents where unit_id = new.unit_id and user_id = auth.uid()) then
        raise exception 'Residents cannot change revoked status';
      end if;
    else
      raise exception 'Only HOA admins can change revoked status';
    end if;
  end if;

  -- If not changing revoked, validate resident updates
  if old.revoked = new.revoked and not public.is_hoa_admin(auth.uid()) then
    if new.valid_until is distinct from old.valid_until then
      raise exception 'Residents cannot change valid_until';
    end if;

    if not exists (select 1 from public.residents where unit_id = new.unit_id and user_id = auth.uid()) then
      raise exception 'Can only update permits for your unit';
    end if;
  end if;

  return new;
end;
